const rows = $input.all();
const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
const now = Date.now();
const due = [];

for (const item of rows) {
  const j = item.json || {};
  const recordId = String(j.id || j.recordId || '');
  const label = String(j.Company || j.Name || j.Title || recordId || 'Untitled');
  const status = String(j.Status?.name || j.Status || '');
  const nextAt = String(j['Next Action At'] || '');
  const next = String(j['Next Action'] || '');

  if (!nextAt) continue;
  const t = Date.parse(nextAt);
  if (!Number.isFinite(t) || t > now) continue;

  const key = [recordId || label, nextAt, next].join('|');
  if (state.seen[key]) continue;

  state.seen[key] = now;
  due.push({ label, status, nextAt, next });
}

const keys = Object.keys(state.seen);
if (keys.length > 1500) {
  keys.sort((a,b) => state.seen[a] - state.seen[b])
      .slice(0, keys.length - 1000)
      .forEach(k => delete state.seen[k]);
}

if (!due.length) return [];

due.sort((a,b) => Date.parse(a.nextAt) - Date.parse(b.nextAt));
const lines = due.map((d,i) =>
  String(i + 1) + '. ' + d.label + ' | ' + (d.status || 'No status') + ' | ' + d.nextAt + '\n   Next: ' + (d.next || '(blank)')
).join('\n\n');

return [{
  json: {
    subject: 'Due next actions: ' + due.length,
    message: 'These items reached their next-action time.\n\n' + lines + '\n\nThis workflow sends an internal alert only. A human decides the next action.'
  }
}];
